using System.Diagnostics;
using Electron2D;
using static TextureArrayTests;

internal static class MeshDataToolTests
{
    internal static void Run()
    {
        Topology(); Channels(); Metadata(); Storage(); Warm();
        Console.WriteLine("MeshDataTool copied triangle topology, nonmanifold/degenerate incidences, finite edits, typed metadata, four/eight channels, atomic commits, fresh archives and warmed zero managed edits/replay passed.");
    }
    private static void Topology()
    {
        using var source = SurfaceToolTests.Mesh(); using var tool = new MeshDataTool(); Check(tool.GetFormat() == 0 && tool.GetVertexCount() == 0 && tool.GetEdgeCount() == 0 && tool.GetFaceCount() == 0, "Empty topology defaults."); Reject<InvalidOperationException>(() => tool.CommitToSurface(source)); tool.CreateFromSurface(source, 0); Check(tool.GetVertexCount() == 4 && tool.GetEdgeCount() == 5 && tool.GetFaceCount() == 2, "Quad triangles build five unique edges.");
        Check(tool.GetFaceVertex(0, 0) == 0 && tool.GetFaceVertex(0, 2) == 2 && tool.GetFaceEdge(0, 0) == 0 && tool.GetFaceEdge(0, 1) == 1 && tool.GetFaceEdge(0, 2) == 2 && tool.GetFaceEdge(1, 0) == 2 && tool.GetFaceEdge(1, 1) == 3 && tool.GetFaceEdge(1, 2) == 4, "Face winding and directed corner edge order."); Check(tool.GetEdgeVertex(2, 0) == 0 && tool.GetEdgeVertex(2, 1) == 2 && tool.GetEdgeFaces(2).SequenceEqual(new[] { 0, 1 }) && tool.GetVertexEdges(0).SequenceEqual(new[] { 0, 2, 4 }) && tool.GetVertexFaces(0).SequenceEqual(new[] { 0, 1 }), "Sorted edge endpoints and discovery-order incidence."); var edges = tool.GetVertexEdges(0); edges[0] = 999; Check(tool.GetVertexEdges(0)[0] == 0, "Relationship queries own their arrays.");
        Check(tool.GetFaceNormal(0) == new Vector3(0, 0, -1), "Face normal derives actual XY winding."); tool.SetVertex(2, new(16, -16)); Check(tool.GetFaceNormal(0).Z == 1 && source.SurfaceGetArrays(0).Vertices[2].Y == 16, "Edited positions recompute normals and isolate source."); tool.SetVertex(2, new(16, 0)); Check(tool.GetFaceNormal(0) == Vector3.Zero, "Collinear face has zero numeric normal."); Reject<ArgumentException>(() => tool.SetVertex(0, new(float.NaN, 0))); Check(tool.GetVertex(0) == Vector2.Zero, "Nonfinite edits retain old values.");
        Reject<ArgumentOutOfRangeException>(() => tool.GetVertex(-1)); Reject<ArgumentOutOfRangeException>(() => tool.GetEdgeVertex(0, 2)); Reject<ArgumentOutOfRangeException>(() => tool.GetFaceVertex(0, 3)); Reject<ArgumentOutOfRangeException>(() => tool.GetFaceEdge(-1, 0)); Reject<ArgumentOutOfRangeException>(() => tool.GetVertexFaces(4)); Reject<ArgumentOutOfRangeException>(() => tool.CreateFromSurface(source, 2)); Check(tool.GetFaceCount() == 2 && tool.GetVertex(2) == new Vector2(16, 0), "Invalid import preserves editing state.");
        using var lines = new ArrayMesh(); lines.AddSurfaceFromArrays(Mesh.PrimitiveType.Lines, new() { Vertices = [Vector2.Zero, Vector2.One] }); Reject<ArgumentException>(() => tool.CreateFromSurface(lines, 0)); Check(tool.GetFaceCount() == 2, "Nontriangle import is rejected atomically.");
        using var nonmanifold = new ArrayMesh(); nonmanifold.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles, new() { Vertices = [Vector2.Zero, Vector2.Right, Vector2.Down, Vector2.One, new(2, 2), new(99, 99)], Indices = [0, 1, 2, 1, 0, 3, 0, 1, 4] }); tool.CreateFromSurface(nonmanifold, 0); Check(tool.GetEdgeFaces(0).SequenceEqual(new[] { 0, 1, 2 }) && tool.GetVertexEdges(5).Length == 0 && tool.GetVertexCount() == 6, "Nonmanifold incidences and unused vertices are preserved.");
        using var degenerate = new ArrayMesh(); degenerate.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles, new() { Vertices = [Vector2.Zero, Vector2.One], Indices = [0, 0, 1] }); tool.CreateFromSurface(degenerate, 0); Check(tool.GetEdgeCount() == 2 && tool.GetEdgeVertex(0, 0) == 0 && tool.GetEdgeVertex(0, 1) == 0 && tool.GetVertexEdges(0).SequenceEqual(new[] { 0, 0, 1 }) && tool.GetVertexFaces(0).SequenceEqual(new[] { 0, 0 }) && tool.GetEdgeFaces(1).SequenceEqual(new[] { 0, 0 }), "Degenerate corners/loops preserve exact multiplicity.");
        using var sequential = new ArrayMesh(); sequential.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles, new() { Vertices = [Vector2.Zero, Vector2.Right, Vector2.Down] }); tool.CreateFromSurface(sequential, 0); Check((tool.GetFormat() & Mesh.ArrayFormat.Index) == 0, "Import format retains original sequential flag."); using var target = new ArrayMesh(); tool.CommitToSurface(target); Check(target.SurfaceGetArrays(0).Indices.SequenceEqual(new[] { 0, 1, 2 }) && (target.SurfaceGetFormat(0) & Mesh.ArrayFormat.Index) != 0, "Commit produces explicit authored face order.");
        using var grid = new ArrayMesh(); grid.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles, SurfaceToolTests.Grid(128)); tool.CreateFromSurface(grid, 0); Check(tool.GetVertexCount() == 129 * 129 && tool.GetFaceCount() == 128 * 128 * 2 && tool.GetEdgeCount() == 3 * 128 * 128 + 2 * 128, "Large connected graph preserves exact boundary/diagonal edge counts."); tool.CreateFromSurface(sequential, 0);
        tool.SetVertex(0, new(-float.MaxValue, -float.MaxValue)); tool.SetVertex(1, new(float.MaxValue, -float.MaxValue)); tool.SetVertex(2, new(0, float.MaxValue)); Check(tool.GetFaceNormal(0).Z == -1, "Widened cross product supports finite extreme positions."); tool.Clear(); Check(tool.GetVertexCount() == 0 && tool.GetFormat() == 0 && tool.GetMaterial() is null, "Clear resets every graph/format/material field."); tool.Dispose(); Reject<ObjectDisposedException>(() => tool.GetFaceCount());
    }
    private static void Channels()
    {
        using var source = new ArrayMesh(); source.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles, new() { Vertices = [Vector2.Zero, Vector2.Right, Vector2.Down] }); using var tool = new MeshDataTool(); tool.CreateFromSurface(source, 0); Check(tool.GetVertexColor(1) == Colors.White && tool.GetVertexUV(1) == Vector2.Zero && tool.GetVertexUV2(1) == Vector2.Zero && tool.GetVertexBones(1).Length == 0, "Absent channels use actual rendering defaults."); tool.SetVertexUV(0, new(.25f, .5f)); tool.SetVertexUV2(0, new(.75f, .5f)); tool.SetVertexColor(0, Colors.Red); Check(tool.GetVertexColor(1) == Colors.White && tool.GetVertexUV2(1) == Vector2.Zero, "New ordinary channels preserve untouched defaults."); Reject<ArgumentException>(() => tool.SetVertexUV2(1, new(float.PositiveInfinity, 0))); Reject<ArgumentException>(() => tool.SetVertexColor(1, new(float.NaN, 0, 0))); Check(tool.GetVertexColor(1) == Colors.White, "Rejected colors/UV2 do not mutate state.");
        using var target = new ArrayMesh(); tool.SetVertexBones(0, [1, 0, 0, 0]); Reject<ArgumentException>(() => tool.CommitToSurface(target)); Check(target.GetSurfaceCount() == 0 && (tool.GetFormat() & Mesh.ArrayFormat.Bones) != 0 && (tool.GetFormat() & Mesh.ArrayFormat.Weights) == 0, "Partial skin activation is visible but cannot publish."); tool.SetVertexWeights(0, [.5f, 0, 0, 0]); Reject<ArgumentOutOfRangeException>(() => tool.SetVertexBones(0, [65536, 0, 0, 0])); Reject<ArgumentException>(() => tool.SetVertexWeights(0, [float.NaN, 0, 0, 0])); Reject<ArgumentException>(() => tool.SetVertexBones(1, [0])); tool.CommitToSurface(target); Check(target.SurfaceGetArrays(0).Bones[0] == 1 && Math.Abs(target.SurfaceGetArrays(0).Weights[0] - .5f) < .00002f, "Four influence storage and target packing execute.");
        using var skin = SurfaceToolTests.Mesh(true); tool.CreateFromSurface(skin, 0); Check(tool.GetVertexBones(0).Length == 8 && tool.GetVertexBones(0)[5] == 5 && tool.GetVertexWeights(0)[5] == 1, "Eight influence import does not truncate to four."); var query = tool.GetVertexBones(0); query[5] = 0; Check(tool.GetVertexBones(0)[5] == 5, "Skin queries copy caller arrays."); tool.SetVertexBones(0, [0, 0, 0, 0, 0, 4, 0, 0]); tool.SetVertexWeights(0, [0, 0, 0, 0, 0, .75f, 0, 0]); tool.CommitToSurface(target); var edited = target.SurfaceGetArrays(1); Check(edited.Bones[5] == 4 && Math.Abs(edited.Weights[5] - .75f) < .00002f && (target.SurfaceGetFormat(1) & Mesh.ArrayFormat.Use8BoneWeights) != 0, "Eight influence edits and flag survive commit.");
        using var material = new CanvasItemMaterial(); tool.SetMaterial(material); var notifications = 0; target.Changed += _ => { notifications++; Check(ReferenceEquals(target.SurfaceGetMaterial(target.GetSurfaceCount() - 1), material), "Target observes geometry/material atomically."); }; tool.CommitToSurface(target); Check(notifications == 1 && tool.GetFaceCount() == 2 && ReferenceEquals(tool.GetMaterial(), material), "Editor preserved after one publication."); using var failure = new ArrayMesh(); failure.Changed += _ => throw new Probe(); Reject<Probe>(() => tool.CommitToSurface(failure)); Check(failure.GetSurfaceCount() == 1 && ReferenceEquals(failure.SurfaceGetMaterial(0), material), "Observer failure retains copied surface/material."); Reject<NotSupportedException>(() => tool.CommitToSurface(failure, (Mesh.ArrayFormat)536870912)); Check(failure.GetSurfaceCount() == 1, "Unknown flags reject without target edits."); tool.Dispose(); Check(!material.IsDisposed, "Editor borrows material.");
    }
    private sealed class Probe : Exception { }
    private sealed class Annotation : IDisposable { internal bool Disposed; public void Dispose() => Disposed = true; }
    private static void Metadata()
    {
        using var source = SurfaceToolTests.Mesh(); using var tool = new MeshDataTool(); tool.CreateFromSurface(source, 0); Check(!tool.TryGetVertexMeta<int>(0, out _), "Missing annotation differs from a default value."); tool.SetVertexMeta(0, 0); Check(tool.GetVertexMeta<int>(0) == 0 && !tool.TryGetVertexMeta<string>(0, out _), "Exact metadata type retained."); tool.SetVertexMeta<string?>(0, null); Check(tool.TryGetVertexMeta<string?>(0, out var nil) && nil is null, "Explicit null retained as present."); Reject<KeyNotFoundException>(() => tool.GetVertexMeta<int>(0)); tool.SetEdgeMeta(0, new Vector2(2, 3)); tool.SetFaceMeta(0, "face"); Check(tool.GetEdgeMeta<Vector2>(0) == new Vector2(2, 3) && tool.GetFaceMeta<string>(0) == "face", "Independent typed vertex/edge/face domains."); var borrowed = new Annotation(); tool.SetVertexMeta(1, borrowed); tool.Clear(); Check(!borrowed.Disposed, "Clear releases annotations without disposal."); tool.CreateFromSurface(source, 0); Check(!tool.TryGetEdgeMeta<Vector2>(0, out _) && !tool.TryGetFaceMeta<string>(0, out _), "Successful import resets annotation arrays."); tool.SetFaceMeta(0, 1); tool.SetEdgeMeta(0, 1); tool.SetVertexMeta(0, 1); for (var i = 0; i < 32; i++) { tool.SetFaceMeta(0, i); tool.SetEdgeMeta(0, i); tool.SetVertexMeta(0, i); }
        var before = GC.GetAllocatedBytesForCurrentThread(); for (var i = 0; i < 2000; i++) { tool.SetFaceMeta(0, i); tool.SetEdgeMeta(0, i); tool.SetVertexMeta(0, i); tool.GetFaceMeta<int>(0); tool.TryGetEdgeMeta<int>(0, out _); tool.GetVertexMeta<int>(0); }
        Check(before == GC.GetAllocatedBytesForCurrentThread(), "Same-type metadata replacements/queries allocate zero managed bytes.");
    }
    private static void Storage()
    {
        using var source = SurfaceToolTests.Mesh(true); using var material = new CanvasItemMaterial { BlendMode = BlendMode.Add }; using var tool = new MeshDataTool(); tool.CreateFromSurface(source, 0); tool.SetMaterial(material); for (var i = 0; i < 4; i++) { tool.SetVertexUV2(i, new(.5f, 0)); tool.SetVertex(i, tool.GetVertex(i) + new Vector2(2, 0)); }
        tool.SetFaceMeta(0, "runtime-only"); using var output = new ArrayMesh(); tool.CommitToSurface(output); var path = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "e2d-topology-" + Guid.NewGuid().ToString("N") + ".e2dres");
        try { ResourceSaver.Save(output, path); var start = new ProcessStartInfo("dotnet") { RedirectStandardOutput = true, RedirectStandardError = true }; start.ArgumentList.Add(typeof(MeshDataToolTests).Assembly.Location); start.Environment.Remove("ELECTRON2D_TEST_MESH_DATA_TOOL_NATIVE"); start.Environment.Remove("ELECTRON2D_TEST_MESH_DATA_TOOL"); start.Environment["ELECTRON2D_TEST_MESH_DATA_TOOL_CHILD"] = path; using var child = Process.Start(start)!; var stdout = child.StandardOutput.ReadToEndAsync(); var stderr = child.StandardError.ReadToEndAsync(); if (!child.WaitForExit(30000)) { child.Kill(true); throw new TimeoutException("MeshDataTool child."); } Check(child.ExitCode == 0 && stdout.GetAwaiter().GetResult().Contains("Fresh topology output passed"), stderr.GetAwaiter().GetResult()); } finally { File.Delete(path); }
    }
    internal static void RunChild(string path)
    {
        using var source = ResourceLoader.Load<ArrayMesh>(path, ResourceLoader.CacheMode.Ignore); using var tool = new MeshDataTool(); tool.CreateFromSurface(source, 0); Check(tool.GetVertex(0).X == 2 && tool.GetVertexUV2(0).X == .5f && tool.GetVertexBones(0).Length == 8 && tool.GetVertexWeights(0)[5] == 1 && tool.GetMaterial() is CanvasItemMaterial { BlendMode: BlendMode.Add } && !tool.TryGetFaceMeta<string>(0, out _), "Fresh output carries edited channels/material and excludes transient annotations."); using var output = new ArrayMesh(); tool.CommitToSurface(output); var node = new Draw(output); using var root = new Node(); root.AddChild(node); using var tree = new SceneTree(root); node.Record(); var vertices = new List<CanvasVertex>(); var batches = new List<CanvasBatch>(); node.AppendCanvas(vertices, batches, Transform.Identity); Check(vertices.Count == 6 && vertices[0].Position.X == 2 && vertices[0].UV2.X == .5f && batches[0].Blend == BlendMode.Add, "Fresh edited geometry/material actually replays."); Console.WriteLine("Fresh topology output passed.");
    }
    private sealed class Draw(Mesh mesh) : Entity { internal void Record() { QueueRedraw(); PrepareCanvas(); } protected override void OnDraw() => DrawMesh(mesh, null); }
    private static void Warm()
    {
        using var source = SurfaceToolTests.Mesh(); using var tool = new MeshDataTool(); tool.CreateFromSurface(source, 0); using var output = new ArrayMesh(); tool.CommitToSurface(output); var node = new Draw(output); using var root = new Node(); root.AddChild(node); using var tree = new SceneTree(root); node.Record(); var vertices = new List<CanvasVertex>(64); var batches = new List<CanvasBatch>(8); void Replay() { vertices.Clear(); batches.Clear(); node.AppendCanvas(vertices, batches, Transform.Identity); }
        for (var i = 0; i < 32; i++) Replay(); var before = GC.GetAllocatedBytesForCurrentThread(); for (var i = 0; i < 64; i++) { tool.SetVertex(0, new(i % 2, 0)); tool.SetVertexUV2(0, new(i % 2, 0)); tool.GetFaceNormal(0); tool.GetFaceEdge(0, 0); Replay(); }
        Check(before == GC.GetAllocatedBytesForCurrentThread(), "Prepared scalar edits/topology queries and committed replay allocate zero managed bytes.");
    }
}
